/// The autofill error information handle.
///
/// **Since Tizen:**
/// - 5.5
/// @nodoc
typedef autofill_error_info_h = ffi.Pointer<autofill_error_info_s>;

/// Enumeration for autofill function error.
///
/// **Since Tizen:**
/// - 5.5
/// @nodoc
abstract class autofill_error_e {
  /// < Successful
  static const int AUTOFILL_ERROR_NONE = 0;

  /// < Invalid parameter
  static const int AUTOFILL_ERROR_INVALID_PARAMETER = -22;

  /// < Permission denied
  static const int AUTOFILL_ERROR_PERMISSION_DENIED = -13;

  /// < Not initialized
  static const int AUTOFILL_ERROR_NOT_INITIALIZED = -50397183;

  /// < Operation failed
  static const int AUTOFILL_ERROR_OPERATION_FAILED = -50397182;

  /// < Out of memory
  static const int AUTOFILL_ERROR_OUT_OF_MEMORY = -12;

  /// < Authentication failed
