  /// < Failed to save autofill data
  static const int AUTOFILL_ERROR_COMMIT_FAILED = -50397180;

  /// < Failed to response fill request
  static const int AUTOFILL_ERROR_FILL_RESPONSE_FAILED = -50397179;

  /// < Unable to connect to Autofill Service
  static const int AUTOFILL_ERROR_SERVICE_NOT_CONNECTED = -50397178;

  /// < Autofill Service is not allowed
  static const int AUTOFILL_ERROR_SERVICE_NOT_ALLOWED = -50397177;

  /// < Autofill Service is not activated
